import subprocess
import time
import json
import platform

LOGFILE_PATH = "logfile.log"

def task_func(interval, duration):
    if interval <= 0 or duration <= 0:
        raise ValueError("Both 'interval' and 'duration' must be greater than zero.")

    data = []
    start_time = time.time()
    end_time = start_time + duration

    while time.time() < end_time:
        current_time = time.time()
        timestamp = time.strftime('%Y-%m-%d %H:%M:%S', time.localtime(current_time))

        system_platform = platform.system()
        if system_platform == "Windows":
            try:
                output = subprocess.check_output("wmic cpu get loadpercentage", shell=True, text=True)
                lines = output.strip().split('\n')
                if len(lines) >= 2:
                    cpu_usage = lines[1].strip()
                    if cpu_usage.isdigit():
                        cpu_usage = float(cpu_usage)
                    else:
                        cpu_usage = 0.0
                else:
                    cpu_usage = 0.0
            except subprocess.CalledProcessError:
                cpu_usage = 0.0
        else:
            try:
                output = subprocess.check_output("top -bn1 | grep \"Cpu(s)\"", shell=True, text=True)
                parts = output.split(',')
                idle_cpu = None
                for part in parts:
                    if 'id' in part:
                        idle_cpu = float(part.split()[0])
                        break
                if idle_cpu is not None:
                    cpu_usage = 100.0 - idle_cpu
                else:
                    cpu_usage = 0.0
            except subprocess.CalledProcessError:
                cpu_usage = 0.0

        data.append({'timestamp': timestamp, 'cpu_usage': cpu_usage})

        sleep_time = interval - (time.time() - current_time)
        if sleep_time > 0:
            time.sleep(sleep_time)

    try:
        with open(LOGFILE_PATH, 'w') as log_file:
            json.dump(data, log_file, indent=4)
        return LOGFILE_PATH
    except IOError:
        return None

import subprocess
import os
import shutil
from glob import glob

def task_func(src_folder, dst_folder):
    """
    Compress all files in the specified source folder using gzip and move the compressed files to a destination folder.
    This operation runs as a background process and returns a dictionary with the operation results.

    Parameters:
    src_folder (str): Path to the source folder containing files to compress.
    dst_folder (str): Path to the destination folder for compressed files.

    Returns:
    dict: A dictionary containing:
        'success': Boolean indicating if all files were processed successfully.
        'message': Descriptive message about the operation result.
        'failed_files': List of filenames that failed to compress or move.
    """
    if not os.path.exists(src_folder):
        return {
            'success': False,
            'message': f'Source folder does not exist: {src_folder}',
            'failed_files': []
        }

    if not os.path.exists(dst_folder):
        try:
            os.makedirs(dst_folder)
        except OSError as e:
            return {
                'success': False,
                'message': f'Failed to create destination folder: {e}',
                'failed_files': []
            }

    files = glob(os.path.join(src_folder, '*'))
    failed_files = []

    for file_path in files:
        if os.path.isfile(file_path):
            try:
                # Compress the file using gzip in background
                subprocess.run(['gzip', '-f', file_path], check=True, capture_output=True)

                # Move the compressed file to destination
                compressed_file = file_path + '.gz'
                if os.path.exists(compressed_file):
                    shutil.move(compressed_file, dst_folder)

            except (subprocess.CalledProcessError, OSError, shutil.Error) as e:
                failed_files.append(os.path.basename(file_path))

    success = len(failed_files) == 0
    message = f'Successfully compressed and moved {len(files) - len(failed_files)} files to {dst_folder}' if success else f'Failed to process {len(failed_files)} files'

    return {
        'success': success,
        'message': message,
        'failed_files': failed_files
    }
